def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 6:
        return 'C'

    last_my, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    dc_count = 0
    recent_start = n - 8 if n > 8 else 0
    recent_opp_d = 0

    for i in range(n):
        my, opp = history[i]
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1
            if i >= recent_start:
                recent_opp_d += 1
        if my == 'D' and opp == 'C':
            dc_count += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_streak += 1
        else:
            break

    if last_opp == 'C':
        if opp_d == 0 and n >= 20:
            return 'D'
        return 'C'

    if last_my == 'C':
        if dc_count > 0 and opp_d_streak <= 1:
            return 'C'
        return 'D'

    if dc_count > 0 and opp_d_streak <= 2 and recent_opp_d <= 5:
        return 'C'

    if dc_count == 0 and opp_c * 7 >= n * 5 and dd_streak >= 3:
        return 'C'

    return 'D'
